ALTER TABLE "payment_orders" DROP CONSTRAINT "payment_orders_pricing_shape_check";--> statement-breakpoint
ALTER TABLE "payment_orders" ADD CONSTRAINT "payment_orders_pricing_shape_check" CHECK (("payment_orders"."pricing_version" IS NULL AND "payment_orders"."purchase_type" IS NULL AND "payment_orders"."base_credits" IS NULL AND "payment_orders"."bonus_rate_bps" IS NULL AND "payment_orders"."bonus_credits" IS NULL) OR ("payment_orders"."pricing_version" IS NOT NULL AND "payment_orders"."purchase_type" IN ('credit_top_up', 'individual_story') AND "payment_orders"."base_credits" IS NOT NULL AND "payment_orders"."bonus_rate_bps" IS NOT NULL AND "payment_orders"."bonus_credits" IS NOT NULL AND "payment_orders"."base_credits" >= 0 AND "payment_orders"."bonus_rate_bps" BETWEEN 0 AND 1800 AND "payment_orders"."bonus_credits" >= 0 AND "payment_orders"."credits_purchased" = "payment_orders"."base_credits" + "payment_orders"."bonus_credits" AND (("payment_orders"."purchase_type" = 'credit_top_up' AND "payment_orders"."base_credits" > 0 AND "payment_orders"."currency" = 'EUR' AND "payment_orders"."amount_minor" = "payment_orders"."base_credits" * 100) OR ("payment_orders"."purchase_type" = 'individual_story' AND "payment_orders"."base_credits" = 0 AND "payment_orders"."bonus_credits" = 0 AND "payment_orders"."bonus_rate_bps" = 0 AND "payment_orders"."currency" = 'EUR' AND "payment_orders"."amount_minor" = 130 AND "payment_orders"."pricing_version" = 'story-direct-eur-v1'))));